() => { const p = document.querySelector('[data-testid=battle-result-panel]'); if (!p) return { panel: null };
  const box = (e) => { const r = e.getBoundingClientRect(); return [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)]; };
  const texts = [...p.querySelectorAll('*')].filter((e) => [...e.childNodes].some((n) => n.nodeType === 3 && n.textContent.trim()) && e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden');
  const glyphs = texts.map((e) => { const range = document.createRange(); const t = [...e.childNodes].find((n) => n.nodeType === 3 && n.textContent.trim()); range.selectNodeContents(t); const r = range.getBoundingClientRect(); const k = r.height / (parseFloat(getComputedStyle(e).lineHeight) || r.height); return { text: t.textContent.trim().slice(0, 20), cls: e.className, fontPx: parseFloat(getComputedStyle(e).fontSize), screenFontPx: Math.round(parseFloat(getComputedStyle(e).fontSize) * (p.getBoundingClientRect().width / (p.offsetWidth || 1)) * 10) / 10, lineBoxH: Math.round(r.height * 10) / 10 }; });
  const screenFonts = glyphs.map((g) => g.screenFontPx);
  const vp = document.querySelector('.play-viewport');
  return { viewport: [innerWidth, innerHeight], panel: box(p), scale: Math.round((p.getBoundingClientRect().width / (p.offsetWidth || 1)) * 1000) / 1000, minScreenFont: Math.min(...screenFonts), maxScreenFont: Math.max(...screenFonts), glyphs, confirm: box(document.querySelector('[data-testid=battle-result-confirm]')), layout: vp?.dataset.touchLayout ?? null, rows: [...document.querySelectorAll('.battle-result-reward-row')].map((r) => r.textContent.replace(/\s+/g, ' ').trim()) }; }
